", @"ambiguity",						  @"Deletion extend", @"del cont",						  @"Deletion open", @"del open",						  @"Insertion extend", @"ins cont",						  @"Insertion open", @"ins open",						  @"Match", @"match",						  @"Mismatch", @"mismatch",						  nil];			[self loadFactoryDefaults:self];	return self;}-(void) windowDidLoad {	// set up the fixed-width font menu	NSFontManager * fontManager = [NSFontManager sharedFontManager];	NSArray * bestBets = [fontManager availableFontNamesWithTraits:NSFixedPitchFontMask + NSBoldFontMask + NSItalicFontMask];	NSString * fName, *famName;	NSFont * foont;	for (fName in bestBets) 	{		foont = [NSFont fontWithName:fName size:0.0];		if (foont != nil) {			famName = [foont familyName];			[fontMenu addItemWithTitle:famName];		}	}	famName = [[NSFont userFixedPitchFontOfSize:0.0] familyName];	[fontMenu addItemWithTitle:famName];	return;		// obsolete?		[[fontMenu menu] setAutoenablesItems:NO];	NSArray * fmenuArray = [fontMenu  itemArray];	NSMenuItem * m;	for (m in fmenuArray) {		if ([NSFont fontWithName:m.title size:0.0] !=nil) {//			self.fontName = m.title;		}		[m setEnabled:[NSFont fontWithName:m.title size:0.0]!=nil];	}	}-(void) adjustFormats{	NSString * kee;	NSMutableDictionary * atz, * userPrefsTemp;	NSDictionary * atznew;	NSFont * foont;	NSFontTraitMask tmask;	NSFontManager * fontManager = [NSFontManager sharedFontManager];	int wt = 5;		userPrefsTemp = [userPrefs mutableCopy]; 	for (kee in formatKeys) 		{			atz = [[userPrefs objectForKey:kee] mutableCopy];			foont = [atz objectForKey:NSFontAttributeName];			if (foont != nil) {				tmask = [fontManager traitsOfFont:foont];				// This step shouldn't be necessary according to NSFontManager specs, but OS 10.5 seems to need it.				if (tmask & NSBoldFontMask) {					wt = 12;				} else {					wt = 5;				}				foont = [fontManager fontWithFamily:fontName traits:tmask weight:wt size:fontSize];				if (foont != nil) {					[atz setObject:foont forKey:NSFontAttributeName];					atznew = [atz copy];					[userPrefsTemp setObject:atznew forKey:kee]; // T3				}			}	}	userPrefs = [userPrefsTemp copy]; }-(NSDictionary *) stripFormat: (NSDictionary *) fmat{	NSMutableDictionary * mat = [fmat mutableCopy];	[mat removeObjectsForKeys:[NSArray arrayWithObjects:NSFontAttributeName, NSForegroundColorAttributeName,nil]];	return [mat copy];}-(void) getFormats{	fontName = [fontMenu titleOfSelectedItem];	NSDictionary * fmat = [missingFString attributesAtIndex:0 effectiveRange:NULL];	fmat = [self stripFormat:fmat];//can't use "self.userPrefs" here because that makes a copy instead of a mutable copy	NSDictionary * temp = [NSMutableDictionary dictionaryWithObjectsAndKeys:				 [joinFString attributesAtIndex:0 effectiveRange:NULL], @"joinFmat", 				 [endFString attributesAtIndex:0 effectiveRange:NULL], @"endFmat", 				 fmat, @"missingFmat", 				 [microFString attributesAtIndex:0 effectiveRange:NULL], @"microFmat",				 [fillerFString attributesAtIndex:0 effectiveRange:NULL], @"fillerFmat",				 [overhangFString attributesAtIndex:0 effectiveRange:NULL], @"overhangFmat",				 [defaultFString attributesAtIndex:0 effectiveRange:NULL], @"defaultFmat",				 [forwardTemplateFString attributesAtIndex:0 effectiveRange:NULL], @"forwardTemplateFmat",				 [reverseTemplateFString attributesAtIndex:0 effectiveRange:NULL], @"reverseTemplateFmat",				 				 [NSNumber numberWithInt:minFillerLength], @"minFillerLength",				 [NSNumber numberWithInt:minFillerPercentMatch], @"minFillerPercentMatch",				 [NSNumber numberWithInt:fontSize], @"fontSize",				 fontName, @"fontName",			     params, @"matchParams",				 nil];	userPrefs = [temp copy];	[self adjustFormats];}-(void) setFormats{	NSAttributedString * ss = [[NSAttributedString alloc] initWithString:[joinFString string] attributes: [userPrefs objectForKey:@"joinFmat"]];	self.joinFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[endFString string] attributes: [userPrefs objectForKey:@"endFmat"]];	self.endFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[microFString string] attributes: [userPrefs objectForKey:@"microFmat"]];	self.microFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[missingFString string] attributes: [userPrefs objectForKey:@"missingFmat"]];	self.missingFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[fillerFString string] attributes: [userPrefs objectForKey:@"fillerFmat"]];	self.fillerFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[overhangFString string] attributes: [userPrefs objectForKey:@"overhangFmat"]];	self.overhangFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[defaultFString string] attributes: [userPrefs objectForKey:@"defaultFmat"]];	self.defaultFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[forwardTemplateFString string] attributes: [userPrefs objectForKey:@"forwardTemplateFmat"]];	self.forwardTemplateFString = [ss mutableCopy];	ss = [[NSAttributedString alloc] initWithString:[reverseTemplateFString string] attributes: [userPrefs objectForKey:@"reverseTemplateFmat"]];	self.reverseTemplateFString = [ss mutableCopy];	self.minFillerLength = [[userPrefs objectForKey:@"minFillerLength"] intValue];	self.minFillerPercentMatch = [[userPrefs objectForKey:@"minFillerPercentMatch"] intValue];	self.fontName = [userPrefs objectForKey:@"fontName"];	self.fontSize = [[userPrefs objectForKey:@"fontSize"] intValue];}-(IBAction) saveParametersAs: (id) sender{	[self getFormats];	NSData * prefsData = [NSArchiver archivedDataWithRootObject:userPrefs];	NSSavePanel * thePanel = [NSSavePanel savePanel];	[thePanel setAllowedFileTypes:[NSArray arrayWithObjects:@"flist", nil]];	[thePanel setAllowsOtherFileTypes:NO];	[thePanel setMessage:@"Save the current preferences to a file ..."];	[thePanel runModal];	if ([thePanel URL]) {	[prefsData writeToURL:[thePanel URL] atomically:YES];	}}-(IBAction) loadParameters: (id) sender{	NSOpenPanel * thePanel = [NSOpenPanel openPanel];	[thePanel setAllowedFileTypes:[NSArray arrayWithObjects:@"flist", nil]];	[thePanel setAllowsOtherFileTypes:NO];	[thePanel setMessage:@"Select file containing list of parameters"];	[thePanel setCanChooseFiles:YES];	[thePanel setCanChooseDirectories:NO];	//[thePanel runModal]; // Only works if compiled for 10.6	[thePanel runModalForTypes:[NSArray arrayWithObjects:@"flist", nil]];	if ([thePanel URLs]) {	//	self.paramsPath = [[[thePanel URLs] objectAtIndex:0] path]; // 10.6 only		NSData * tempData = [NSData dataWithContentsOfURL:[[thePanel URLs] objectAtIndex:0]];//		NSDictionary * regenerated = [NSUnarchiver unarchiveObjectWithData:tempData];		userPrefs = [NSUnarchiver unarchiveObjectWithData:tempData];		self.fontName = [userPrefs objectForKey:@"fontName"];		self.fontSize = [[userPrefs objectForKey:@"fontSize"] intValue];		self.minFillerLength = [[userPrefs objectForKey:@"minFillerLength"] intValue];		self.minFillerPercentMatch = [[userPrefs objectForKey:@"minFillerPercentMatch"]  intValue];		self.params = [userPrefs objectForKey:@"matchParams"];				[self adjustFormats];		[self setFormats];	}}-(IBAction) loadFactoryDefaults: (id) sender {				NSData * tempData = [NSData dataWithContentsOfFile:factoryDefaultsPath];	userPrefs = [NSUnarchiver unarchiveObjectWithData:tempData];	self.params = [userPrefs objectForKey:@"matchParams"];	self.fontName = [userPrefs objectForKey:@"fontName"];		self.fontSize = [[userPrefs objectForKey:@"fontSize"] intValue];	self.minFillerLength = [[userPrefs objectForKey:@"minFillerLength"] intValue];	self.minFillerPercentMatch = [[userPrefs objectForKey:@"minFillerPercentMatch"]  intValue];		NSFontManager * fontManager = [NSFontManager sharedFontManager];	NSArray * bestBets = [fontManager availableFontNamesWithTraits:NSFixedPitchFontMask + NSBoldFontMask + NSItalicFontMask];	NSString * fName;	NSFont * foont;	uint32_t traits;	NSMutableDictionary * mutableUserPrefs, *mutableAttributes;	mutableUserPrefs = [userPrefs mutableCopy];		if ([NSFont fontWithName:fontName size:0.0] == nil) {		if (bestBets.count == 0) {			self.fontName = [[NSFont userFixedPitchFontOfSize:fontSize] familyName];		} else {			foont = [NSFont fontWithName:[bestBets objectAtIndex:0] size:0.0];			if (foont != nil) {				self.fontName = [foont familyName]; // this font might be serif			}			// now try to find one sanserif			for (fName in bestBets) 			{				foont = [NSFont fontWithName:fName size:0.0];				if (foont != nil) {					traits = [[foont fontDescriptor] symbolicTraits];					if (traits & NSFontSansSerifClass) {						self.fontName = [foont familyName];						[mutableUserPrefs setObject:fontName forKey:@"fontName"];					}				}			}		}				//For some reason, MacOS 10.5 requires the boldface be made re-applied to these two joinFmat and microFmat		mutableAttributes = [[userPrefs objectForKey:@"joinFmat"] mutableCopy];		foont = [mutableAttributes objectForKey:NSFontAttributeName];		if (foont != nil) {			foont = [NSFont fontWithName:fontName size:fontSize];			foont = [fontManager convertFont:foont toHaveTrait: NSBoldFontMask];			[mutableAttributes setObject:foont forKey:NSFontAttributeName];			[mutableUserPrefs setObject:[mutableAttributes copy] forKey:@"joinFmat"];		}		mutableAttributes = [[userPrefs objectForKey:@"microFmat"] mutableCopy];		foont = [mutableAttributes objectForKey:NSFontAttributeName];		if (foont != nil) {			foont = [NSFont fontWithName:fontName size:fontSize];			foont = [fontManager convertFont:foont toHaveTrait: NSBoldFontMask];			[mutableAttributes setObject:foont forKey:NSFontAttributeName];			[mutableUserPrefs setObject:[mutableAttributes copy] forKey:@"microFmat"];		}		mutableAttributes = [[userPrefs objectForKey:@"overhangFmat"] mutableCopy];		foont = [mutableAttributes objectForKey:NSFontAttributeName];		if (foont != nil) {			foont = [NSFont fontWithName:fontName size:fontSize];			foont = [fontManager convertFont:foont toHaveTrait: NSBoldFontMask];			foont = [fontManager convertFont:foont toHaveTrait: NSItalicFontMask];			[mutableAttributes setObject:foont forKey:NSFontAttributeName];			[mutableUserPrefs setObject:[mutableAttributes copy] forKey:@"overhangFmat"];		}				userPrefs = [mutableUserPrefs copy];		[self adjustFormats];	}	[self setFormats];}-(IBAction) closeSelf: (id) sender{	[self getFormats];	[panel performClose:self];}-(IBAction) tinker: (id) sender {	[self getFormats];	[self setFormats];	return;						  }@end